{
  "story": "A four-stroke engine converts fuel energy into motion through intake, compression, power, and exhaust stages.",
  "aha": {
    "stateId": "power",
    "observation": "The downward expansion of hot combustion gases drives the piston, delivering the actual work."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "metrics",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Engine Stroke",
      "options": ["intake", "compression", "power", "exhaust"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset Cycle"
    }
  ],
  "data": {
    "variants": [
      {
        "regions": [
          {
            "id": "valveIn",
            "label": "Intake Valve",
            "kind": "valve",
            "phases": ["open", "closed", "closed", "closed"]
          },
          {
            "id": "valveEx",
            "label": "Exhaust Valve",
            "kind": "valve",
            "phases": ["closed", "closed", "closed", "open"]
          },
          {
            "id": "piston",
            "label": "Piston",
            "kind": "piston",
            "phases": ["down", "up", "down", "up"]
          },
          {
            "id": "spark",
            "label": "Spark Plug",
            "kind": "igniter",
            "phases": ["off", "off", "fire", "off"]
          }
        ],
        "states": [
          {
            "id": "intake",
            "label": "1. Intake",
            "short": "Intake",
            "sentence": "The intake valve opens as the piston descends, drawing air and fuel into the cylinder.",
            "why": "Low pressure created by the moving piston pulls the mixture inward.",
            "active": ["valveIn", "piston"],
            "calloutRegion": "valveIn",
            "readouts": [
              {"id": "pPos", "label": "Piston Position", "value": "Top to Bottom"},
              {"id": "press", "label": "Cylinder Pressure", "value": "0.9 bar"}
            ]
          },
          {
            "id": "compression",
            "label": "2. Compression",
            "short": "Compression",
            "sentence": "Both valves close, and the piston ascends to compress the air-fuel mixture.",
            "why": "Higher density and pressure prepare the mixture for rapid, efficient burning.",
            "active": ["piston"],
            "calloutRegion": "piston",
            "readouts": [
              {"id": "pPos", "label": "Piston Position", "value": "Bottom to Top"},
              {"id": "press", "label": "Cylinder Pressure", "value": "12.0 bar"}
            ]
          },
          {
            "id": "power",
            "label": "3. Power",
            "short": "Power",
            "sentence": "The spark plug ignites the mixture, and expanding gases forcefully push the piston down.",
            "why": "Thermal energy converts into mechanical work at the crankshaft.",
            "active": ["spark", "piston"],
            "calloutRegion": "spark",
            "readouts": [
              {"id": "pPos", "label": "Piston Position", "value": "Top to Bottom"},
              {"id": "press", "label": "Cylinder Pressure", "value": "55.0 bar"}
            ]
          },
          {
            "id": "exhaust",
            "label": "4. Exhaust",
            "short": "Exhaust",
            "sentence": "The exhaust valve opens as the piston rises again, pushing spent gases out.",
            "why": "Clearing the cylinder prepares the engine for the next intake stroke.",
            "active": ["valveEx", "piston"],
            "calloutRegion": "valveEx",
            "readouts": [
              {"id": "pPos", "label": "Piston Position", "value": "Bottom to Top"},
              {"id": "press", "label": "Cylinder Pressure", "value": "1.1 bar"}
            ]
          }
        ]
      }
    ]
  }
}
